arguments.command:
python3 - <<'EOF'
p='src/triggers.ts'
s=open(p).read()
s=s.replace("""	/** Set when this is the answer to a question from a pi-durable extension; `text` is the message for the model. */
	answer?: UiAnswer;
}""","""	/** Set when this is the answer to a question from a pi-durable extension; `text` is the message for the model. */
	answer?: UiAnswer;
	/** Set when `task` is a prompt template's expanded body; `typed` is the task as written (`/name args`). */
	template?: { name: string; source: string; typed: string };
}""")
open(p,'w').write(s)

p='src/conversation.ts'
s=open(p).read()
old="""				...(trigger.url ? { url: trigger.url } : {}),
			},"""
assert old in s
s=s.replace(old,"""				...(trigger.url ? { url: trigger.url } : {}),
				...(trigger.template
					? { template: trigger.template.name, typed: trigger.template.typed }
					: {}),
			},""")
open(p,'w').write(s)
EOF
